-- P0-08: original iClub P5 Representation mixed beta set.
-- DRAFT + INACTIVE only; no learner exposure and no existing-question mutation.
begin;
with cv as (select id from private.exam_prep_content_versions where content_version='p5_repr_beta_v1' and component_code='P5' and status='draft'), src(content_key,skill_code,reserve_role,topic,subtopic,difficulty,qtype,q_en,opts_en,correct_answer,exp_en,q_ru,q_uz,q_en_dup,opts_ru,opts_uz,opts_en_dup,exp_ru,exp_uz,exp_en_dup,book_ref,time_limit_sec,secondary_csv) as (values
('P5MIX-M01','P5-DAT-04','mixed','P5 Representation of data','P5-DAT-04','medium','mcq','Waiting times are continuous and grouped into unequal class widths. For the class 10 ≤ t < 15, the frequency is 20. Which statement gives both an appropriate display and the correct bar height for this class?','["Histogram; height 4", "Histogram; height 20", "Bar chart; height 4", "Box plot; height 20"]','A','Unequal-width grouped continuous data require a histogram. The class width is 5, so frequency density and bar height are 20/5 = 4.','Время ожидания — непрерывная величина, сгруппированная в интервалы разной ширины. Для интервала 10 ≤ t < 15 частота равна 20. Какое утверждение правильно указывает и подходящую диаграмму, и высоту столбца для этого интервала?','Kutish vaqti uzluksiz bo‘lib, turli kenglikdagi intervallarga guruhlangan. 10 ≤ t < 15 intervalida chastota 20. Qaysi javob mos tasvirlash usuli va shu interval ustunining to‘g‘ri balandligini birga beradi?','Waiting times are continuous and grouped into unequal class widths. For the class 10 ≤ t < 15, the frequency is 20. Which statement gives both an appropriate display and the correct bar height for this class?','["Histogram; height 4", "Histogram; height 20", "Bar chart; height 4", "Box plot; height 20"]','["Histogram; height 4", "Histogram; height 20", "Bar chart; height 4", "Box plot; height 20"]','["Histogram; height 4", "Histogram; height 20", "Bar chart; height 4", "Box plot; height 20"]','Для непрерывных сгруппированных данных с неравными интервалами нужна гистограмма. Ширина интервала 5, поэтому плотность частоты и высота столбца равны 20/5 = 4.','Turli kenglikdagi intervallarga guruhlangan uzluksiz ma’lumotlar uchun gistogramma kerak. Interval kengligi 5, shuning uchun chastota zichligi va ustun balandligi 20/5 = 4.','Unequal-width grouped continuous data require a histogram. The class width is 5, so frequency density and bar height are 20/5 = 4.','ExamPrep:P5:p5_repr_beta_v1:P5MIX-M01',75,'P5-DAT-01'),
('P5MIX-M02','P5-DAT-06','mixed','P5 Representation of data','P5-DAT-06','medium','mcq','For the data 2, 4, 6, 8, 10, the mean is required, and the result will later be compared with another dataset using median and spread. Which pair is correct?','["Mean 5; pie chart", "Mean 6; side-by-side box plots", "Mean 6; scatter plot", "Mean 8; line graph"]','B','The mean is 30/5 = 6. Side-by-side box plots are suitable for comparing median and spread between datasets.','Для данных 2, 4, 6, 8, 10 требуется найти среднее, а затем результат будут сравнивать с другим набором по медиане и разбросу. Какая пара верна?','2, 4, 6, 8, 10 ma’lumotlari uchun o‘rtacha topiladi, so‘ng natija boshqa to‘plam bilan mediana va tarqalish bo‘yicha taqqoslanadi. Qaysi juftlik to‘g‘ri?','For the data 2, 4, 6, 8, 10, the mean is required, and the result will later be compared with another dataset using median and spread. Which pair is correct?','["Mean 5; pie chart", "Mean 6; side-by-side box plots", "Mean 6; scatter plot", "Mean 8; line graph"]','["Mean 5; pie chart", "Mean 6; side-by-side box plots", "Mean 6; scatter plot", "Mean 8; line graph"]','["Mean 5; pie chart", "Mean 6; side-by-side box plots", "Mean 6; scatter plot", "Mean 8; line graph"]','Среднее равно 30/5 = 6. Для сравнения медианы и разброса наборов подходят расположенные рядом диаграммы «ящик с усами».','O‘rtacha 30/5 = 6. To‘plamlarning mediana va tarqalishini taqqoslash uchun yonma-yon quti-mo‘ylov diagrammalari mos.','The mean is 30/5 = 6. Side-by-side box plots are suitable for comparing median and spread between datasets.','ExamPrep:P5:p5_repr_beta_v1:P5MIX-M02',75,'P5-DAT-01'),
('P5MIX-M03','P5-DAT-01','mixed','P5 Representation of data','P5-DAT-01','medium','mcq','A small dataset contains one unusually large value. An analyst wants a display that makes the median and interquartile spread easy to compare with another dataset. Which choice is most suitable?','["Pie chart using the mean", "Scatter plot using the mode", "Side-by-side box plots using median and quartiles", "Line graph using frequency density"]','C','Box plots display the median and quartiles directly and are useful when comparing spread in the presence of extreme values.','В небольшом наборе данных есть одно необычно большое значение. Аналитик хочет диаграмму, на которой удобно сравнить медиану и межквартильный разброс с другим набором. Какой выбор наиболее подходит?','Kichik ma’lumotlar to‘plamida bitta juda katta qiymat bor. Tahlilchi medianani va kvartillararo tarqalishni boshqa to‘plam bilan oson taqqoslaydigan tasvirlash usulini xohlaydi. Qaysi tanlov eng mos?','A small dataset contains one unusually large value. An analyst wants a display that makes the median and interquartile spread easy to compare with another dataset. Which choice is most suitable?','["Pie chart using the mean", "Scatter plot using the mode", "Side-by-side box plots using median and quartiles", "Line graph using frequency density"]','["Pie chart using the mean", "Scatter plot using the mode", "Side-by-side box plots using median and quartiles", "Line graph using frequency density"]','["Pie chart using the mean", "Scatter plot using the mode", "Side-by-side box plots using median and quartiles", "Line graph using frequency density"]','Диаграммы «ящик с усами» напрямую показывают медиану и квартили и удобны для сравнения разброса при наличии крайних значений.','Quti-mo‘ylov diagrammalari mediana va kvartillarni bevosita ko‘rsatadi va chekka qiymatlar mavjud bo‘lganda tarqalishni taqqoslash uchun qulay.','Box plots display the median and quartiles directly and are useful when comparing spread in the presence of extreme values.','ExamPrep:P5:p5_repr_beta_v1:P5MIX-M03',70,'P5-DAT-06'))
insert into public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
select 5,s.topic,s.subtopic,s.difficulty,s.qtype,s.q_en,s.opts_en,s.correct_answer,s.exp_en,null,false,s.q_ru,s.q_uz,s.q_en_dup,s.opts_ru,s.opts_uz,s.opts_en_dup,s.exp_ru,s.exp_uz,s.exp_en_dup,s.book_ref,s.time_limit_sec,null,'draft' from src s where not exists(select 1 from public.questions q where q.book_ref=s.book_ref);
with cv as (select id from private.exam_prep_content_versions where content_version='p5_repr_beta_v1' and component_code='P5' and status='draft'), src(content_key,skill_code,reserve_role,secondary_csv,book_ref) as (values ('P5MIX-M01','P5-DAT-04','mixed','P5-DAT-01','ExamPrep:P5:p5_repr_beta_v1:P5MIX-M01'),('P5MIX-M02','P5-DAT-06','mixed','P5-DAT-01','ExamPrep:P5:p5_repr_beta_v1:P5MIX-M02'),('P5MIX-M03','P5-DAT-01','mixed','P5-DAT-06','ExamPrep:P5:p5_repr_beta_v1:P5MIX-M03'))
insert into private.exam_prep_question_content_meta(content_version_id,content_key,question_id,primary_skill_code,secondary_skill_codes,reserve_role,exposure_state,lifecycle_state,originality_attestation,provenance_note,official_scope_ref,coursebook_mapping_ref,copyright_status,qa_scope_status,qa_math_status,qa_language_status,qa_technical_status,diagnostic_rule_status,question_snapshot_md5)
select cv.id,s.content_key,q.id,s.skill_code,case when nullif(s.secondary_csv,'') is null then '{}'::text[] else string_to_array(s.secondary_csv,',') end,s.reserve_role,'withheld','draft','Original iClub-authored stem, data, distractors, answer and explanation; no Cambridge/coursebook question text, diagram or mark-scheme wording copied.','Authored specifically for p5_repr_beta_v1 from canonical skill intent and independent numeric/context examples.','Cambridge 9709 2026-2027 v4; P5 5.1 Representation of data',case when s.skill_code='P5-DAT-04' then 'Complete Probability & Statistics 1, Ch3 pp.34-59 (mapping only)' when s.skill_code='P5-DAT-06' then 'Complete Probability & Statistics 1, Ch2 pp.14-29 (mapping only)' else 'Complete Probability & Statistics 1, Ch2-3 pp.14-59 (mapping only)' end,'pending','pending','pending','pending','pending','not_applicable',md5(concat_ws(chr(31),q.id::text,q.subject_id::text,coalesce(q.topic,''),coalesce(q.subtopic,''),coalesce(q.difficulty,''),coalesce(q.qtype,''),coalesce(q.question_text,''),coalesce(q.options_text,''),coalesce(q.correct_answer,''),coalesce(q.explanation,''),coalesce(q.image_url,''),coalesce(q.is_active::text,''),coalesce(q.question_text_ru,''),coalesce(q.question_text_uz,''),coalesce(q.question_text_en,''),coalesce(q.options_text_ru,''),coalesce(q.options_text_uz,''),coalesce(q.options_text_en,''),coalesce(q.explanation_ru,''),coalesce(q.explanation_uz,''),coalesce(q.explanation_en,''),coalesce(q.book_ref,''),coalesce(q.time_limit_sec::text,''),coalesce(q.quality_flag,''),coalesce(q.quality_status,''))) from cv cross join src s join public.questions q on q.book_ref=s.book_ref on conflict(content_version_id,content_key) do nothing;
commit;
